int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (drive >= N_DRIVE || !floppy_drives[drive].exists) {
            return -EINVAL;
        }

        if (type >= N_SUPPORTED_FLOPPY_TYPES) {
            return -EINVAL;
        }

        if (type != FLOPPY_TYPE_CURRENT(drive)) {
            FLOPPY_TYPE(drive) = type;
            update_drive_params(drive);
        }
    } else {
        if (drive >= N_DRIVE || !floppy_drives[drive].exists) {
            return -EINVAL;
        }

        if (check_disk_change(drive)) {
            reset_drive(drive);
        }

        memcpy(&floppy_drives[drive].params, g, sizeof(struct floppy_struct));
        invalidate_floppy_buffers(bdev);
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (type >= N_SUPPORTED_TYPES || type < 0) {
            return -EINVAL;
        }

        /* Update the floppy type */
        FDC_STATE(drive).type = type;
        FDC_STATE(drive).size = g->size;
        FDC_STATE(drive).cylinder = g->cylinder;
        FDC_STATE(drive).head = g->head;
        FDC_STATE(drive).sector = g->sector;
        FDC_STATE(drive).wp = g->wp;

    } else {
        if (drive_info[drive].fd_device != NULL && drive_info[drive].fd_device->nr_parts) {
            return -EINTR;
        }

        if (check_disk_change(drive)) {
            return -ENODEV;
        }

        /* Update user parameters and manage buffer cache */
        g->cylinder = FDC_STATE(drive).cylinder;
        g->head = FDC_STATE(drive).head;
        g->sector = FDC_STATE(drive).sector;
        g->wp = FDC_STATE(drive).wp;
        g->size = FDC_STATE(drive).size;
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE || (type != -1 && type >= MAX floppy_type)) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }
        /* Update floppy type and sizes */
        if (type >= N_FLOPPIES || !floppy_type[type].name) {
            return -EINVAL;
        }
        if (drive_info[drive].type != type) {
            drive_info[drive].type = type;
            drive_info[drive].size = floppy_type[type].size;
            drive_info[drive].track_bytes = floppy_type[type].track_bytes;
            drive_info[drive].sector_offset = floppy_type[type].sector_offset;
        }
    } else {
        if (!g->track_bytes || !g->size) {
            return -EINVAL;
        }
        /* Check for disk changes */
        if (disk_change(drive)) {
            invalidate_disk_cache(drive);
        }
        drive_info[drive].track_bytes = g->track_bytes;
        drive_info[drive].sector_offset = g->sector_offset;
        drive_info[drive].size = g->size;
    }

    /* Ensure buffer cache is consistent */
    invalidate_dirty_buffers(drive);

    return 0;
}
